 	trace_rxrpc_rx_response(conn, sp->hdr.serial, version, kvno, ticket_len);

 	if (version != RXKAD_VERSION) {
-		rxrpc_abort_conn(conn, skb, RXKADINCONSISTENCY, -EPROTO,
